package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import java.time.YearMonth;
public class WakeStatsWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_wake_stats);WakeStats.MonthStats s=WakeStats.forMonth(c,YearMonth.now());String rate=s.ratePercent()<0?"--":s.ratePercent()+"%";r.setTextViewText(R.id.stats_rate,rate);r.setTextViewText(R.id.stats_detail,I18n.tr(c,"成功")+" "+s.wins+"  ·  "+I18n.tr(c,"失敗")+" "+s.losses+"  ·  "+I18n.tr(c,"予定")+" "+s.pending);r.setTextViewText(R.id.stats_streak,"🔥 "+StreakTracker.displayCurrent(c)+I18n.tr(c,"日"));r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,StatsActivity.class,null,null,29000+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
